const FRAG = `#version 300 es
precision highp float;
in vec2 uv;
out vec4 outColor;
uniform vec2 uRes;
uniform float uPx, uTime, uSpacing, uRow, uThick, uTaper, uSpeed, uAniso;
uniform vec2 uOff;
uniform int uShape;
uniform vec3 uA, uB;

void main() {
  vec2 f = gl_FragCoord.xy / uPx;
  vec2 size = uRes / uPx;
  vec2 c = size * (vec2(0.5) + uOff);
  float x = f.x;
  float y = size.y - f.y;
  float dx = x - c.x;
  float dy = (floor((y - c.y) / uRow) + 0.5) * uRow * uAniso;
  float ax = abs(dx), ay = abs(dy);
  float d;
  if (uShape == 0) d = ax + ay;
  else if (uShape == 1) d = length(vec2(dx, dy));
  else if (uShape == 2) d = max(ax, ay);
  else { float s = sqrt(ax) + sqrt(ay); d = s * s * 0.5; }
  float phase = d / uSpacing - uTime * uSpeed;
  float fr = fract(phase);
  float u = clamp(f.x / size.x, 0.0, 1.0);
  float duty = uThick * (1.0 - uTaper * 0.92 * u);
  float aa = max(fwidth(phase), 0.001) * 0.75;
  // stripe centered in the period
  float t = abs(fr - 0.5);
  float m = 1.0 - smoothstep(duty * 0.5 - aa, duty * 0.5 + aa, t);
  // soften when stripes get sub-pixel to avoid moire noise
  m = mix(m, duty, smoothstep(0.35, 1.0, aa * 2.0));
  outColor = vec4(mix(uA, uB, m), 1.0);
}`;

defineTool({
  animated: true,
  setup(ctx) {
    ctx.state.prog = kit.gl.program(ctx.gl, FRAG);
  },
  render(ctx, p) {
    const c = (hex) => kit.color.parse(hex).map((v) => v / 255);
    const r = kit.rand(p.seed * 7 + 1);
    const offx = (r() - 0.5) * 0.3, offy = (r() - 0.5) * 0.3;
    const aniso = 0.8 + r() * 0.5;
    const shapes = { diamond: 0, circle: 1, square: 2, star: 3 };
    ctx.state.prog.draw({
      uRes: [ctx.width, ctx.height],
      uPx: ctx.px,
      uTime: ctx.time,
      uSpacing: p.spacing,
      uRow: p.rowHeight,
      uThick: p.thickness,
      uTaper: p.taper,
      uSpeed: p.speed,
      uAniso: aniso,
      uOff: [offx, offy],
      uShape: shapes[p.shape] || 0,
      uA: c(p.colorA),
      uB: c(p.colorB),
    });
  },
});

const TAU = Math.PI * 2;
const KINDS = {
  pcb: [['qfp', 'conn', 'qfp', 'conn'], ['soic', 'header', 'button', 'cap', 'soic', 'xtal', 'vias'], ['smd', 'smd', 'smd', 'xtal', 'vias']],
  schematic: [['ic', 'ic'], ['opamp', 'tr', 'seg', 'ic', 'tr', 'tr'], ['res', 'res', 'cap2', 'diode', 'res', 'cap2']],
};
KINDS.mixed = KINDS.pcb.map((a, i) => a.concat(KINDS.schematic[i]));
const PREFIX = { qfp: 'U', ic: 'U', soic: 'U', opamp: 'U', conn: 'J', header: 'J', button: 'SW', cap: 'C', cap2: 'C', xtal: 'Y', smd: 'R', res: 'R', diode: 'D', tr: 'Q', seg: 'DS', vias: '' };

const VALUES = {
  res: ['10k', '4.7k', '220R', '1M', '47k', '330R', '100R', '2.2k'], smd: ['10k', '4.7k', '100R', '0R', '1k', '22R'],
  cap: ['100uF', '470uF', '220uF', '1000uF'], cap2: ['100nF', '10uF', '22pF', '1uF', '4.7nF', '33pF'],
  xtal: ['16MHz', '32.768k', '8MHz', '12MHz', '25MHz'], diode: ['1N4148', '1N4007', 'BAT54', 'LED'],
  tr: ['2SC1815', '2SA1015', 'BC547', '2N3904', 'BC557'], opamp: ['LM358', 'TL072', 'NE5532', 'LM324'],
  ic: ['74HC595', 'NE555', 'ATMEGA328', 'CD4017', '74LS04', 'MAX232', 'LM317'], soic: ['74HC14', 'AMS1117', 'CH340G', '24LC256', 'LM393'],
  qfp: ['STM32F407', 'ATSAMD21', 'RP2040', 'ESP32-S3', 'XC6SLX9'], conn: ['GPIO', 'EXP BUS', 'PCIE', 'DDR SLOT'],
  header: ['JTAG', 'PWR', 'I2C', 'UART', 'SPI'], button: ['RESET', 'BOOT', 'USER'], seg: ['DISP', 'LED7'],
};

function rng(n, st = 1) { const a = []; for (let i = 0; i < n; i += st) a.push(i); return a; }

function spec(kind, r, s) {
  const S = (a, b) => Math.max(1, Math.round(r.int(a, b) * s));
  switch (kind) {
    case 'qfp': { const n = Math.max(6, S(8, 16)), st = r.pick([1, 1, 2]); return { w: n, h: n, L: rng(n, st), R: rng(n, st), T: rng(n, st), B: rng(n, st) }; }
    case 'conn': { const n = Math.max(8, S(14, 30)); return { w: n, h: 2, T: rng(n), B: r.chance(0.5) ? rng(n, 2) : [], rot: true }; }
    case 'soic': { const n = Math.max(3, S(4, 9)); return { w: 3, h: n, L: rng(n), R: rng(n), rot: true }; }
    case 'header': { const n = Math.max(2, S(3, 7)); return { w: 2, h: n, L: rng(n), rot: true }; }
    case 'button': { const n = Math.max(3, S(3, 4)); return { w: n, h: n, L: [n >> 1], R: [n >> 1] }; }
    case 'cap': { const n = Math.max(2, S(2, 4)); return { w: n, h: n, L: [n >> 1], R: [n >> 1], rot: true }; }
    case 'xtal': return { w: Math.max(3, S(3, 4)), h: 1, L: [0], R: [0], rot: true };
    case 'smd': return { w: 2, h: 1, L: [0], R: [0], rot: true };
    case 'vias': return { w: 2, h: 2 };
    case 'ic': { const w = Math.max(3, S(4, 7)), h = Math.max(4, S(6, 14)), st = r.pick([1, 2]); return { w, h, L: rng(h, st), R: rng(h, st), T: r.chance(0.3) ? rng(w, 2) : [], rot: true }; }
    case 'opamp': return { w: 3, h: 3, L: [0, 2], R: [1] };
    case 'tr': return { w: 3, h: 3, L: [1], T: [2], B: [2] };
    case 'seg': { const w = Math.max(3, S(3, 6)); return { w, h: 4, B: rng(w) }; }
    case 'res': case 'diode': return { w: 3, h: 1, L: [0], R: [0], rot: true };
    default: return { w: 2, h: 1, L: [0], R: [0], rot: true }; // cap2
  }
}

function simplify(pts) {
  const o = [];
  for (const q of pts) { const l = o[o.length - 1]; if (!l || l[0] !== q[0] || l[1] !== q[1]) o.push(q); }
  if (o.length < 3) return o;
  const out = [o[0]];
  for (let k = 1; k < o.length - 1; k++) {
    const a = out[out.length - 1], b = o[k], c = o[k + 1];
    if ((a[0] === b[0] && b[0] === c[0]) || (a[1] === b[1] && b[1] === c[1])) continue;
    out.push(b);
  }
  out.push(o[o.length - 1]);
  return out;
}

function build(p, cols, rows, reserve) {
  const r = kit.rand(p.seed);
  const grid = new Uint8Array(cols * rows);
  const at = (x, y) => (x < 0 || y < 0 || x >= cols || y >= rows ? 255 : grid[y * cols + x]);
  const set = (x, y, v) => { if (x >= 0 && y >= 0 && x < cols && y < rows) grid[y * cols + x] = v; };
  const free = (x, y) => at(x, y) === 0;
  // Density map: 1 = full density, lower = emptier areas.
  const nz = kit.noise(p.seed * 31 + 7), asp = Math.max(cols, rows);
  const maskAt = (x, y) => {
    if (p.maskType === 'none' || p.maskStrength <= 0) return 1;
    const mu = (x / asp) * p.maskScale, mv = (y / asp) * p.maskScale;
    let m;
    switch (p.maskType) {
      case 'ridges': m = nz.ridged2(mu, mv, 5) * 1.1; break;
      case 'cells': m = kit.math.clamp(nz.worley2(mu * 1.2, mv * 1.2) * 1.4, 0, 1); break;
      case 'islands': m = kit.math.smoothstep(-0.15, 0.25, nz.simplex2(mu * 0.7, mv * 0.7)); break;
      case 'radial': { const dx = x / cols - 0.5, dy = y / rows - 0.5; m = 1.15 - Math.hypot(dx, dy) * 2.2 + nz.fbm2(mu, mv, 4) * 0.3; break; }
      default: m = nz.fbm2(mu, mv, 5) * 0.9 + 0.5;
    }
    if (p.maskInvert) m = 1 - m;
    return 1 - p.maskStrength * (1 - kit.math.smoothstep(0.38, 0.62, m));
  };
  const comps = [], traces = [], ends = [], vias = [], holes = [], dots = [];
  const sch = p.style !== 'pcb';
  if (p.frame) for (const [hx, hy] of [[0, 0], [cols - 3, 0], [0, rows - 3], [cols - 3, rows - 3]]) {
    holes.push([hx + 1, hy + 1]);
    for (let j = 0; j < 3; j++) for (let i = 0; i < 3; i++) set(hx + i, hy + j, 1);
  }
  if (reserve) for (let j = reserve.y - 1; j < reserve.y + reserve.h + 1; j++) for (let i = reserve.x - 1; i < reserve.x + reserve.w + 1; i++) set(i, j, 1);
  const kinds = KINDS[p.style] || KINDS.pcb;
  const area = cols * rows, counters = {};
  const target = 1 + Math.round((area / 7000) * p.density);
  const tries = [60, Math.round((area / 130) * p.density), Math.round((area / 80) * p.density)];
  for (let cls = 0; cls < 3; cls++) {
    let placed = 0;
    for (let t = 0; t < tries[cls]; t++) {
      if (cls === 0 && placed >= target) break;
      const kind = r.pick(kinds[cls]);
      let s = spec(kind, r, p.compScale);
      if (s.rot && r.chance(0.5)) s = { w: s.h, h: s.w, L: s.T, T: s.L, R: s.B, B: s.R };
      const pad = cls === 2 ? 1 : 2;
      if (s.w + 2 * pad >= cols || s.h + 2 * pad >= rows) continue;
      const x = r.int(pad, cols - s.w - pad), y = r.int(pad, rows - s.h - pad);
      const kp = maskAt(x + s.w / 2, y + s.h / 2);
      if (kp < 1 && r() > (cls === 0 ? 0.35 + 0.65 * kp : kp)) continue;
      let ok = true;
      for (let j = y - pad; j < y + s.h + pad && ok; j++) for (let i = x - pad; i < x + s.w + pad; i++) if (at(i, j) !== 0) { ok = false; break; }
      if (!ok) continue;
      for (let j = y; j < y + s.h; j++) for (let i = x; i < x + s.w; i++) set(i, j, 1);
      const pre = PREFIX[kind];
      counters[pre] = (counters[pre] || 0) + 1;
      const c = { kind, x, y, w: s.w, h: s.h, pins: [], label: pre ? pre + counters[pre] : '' };
      const add = (arr, f) => { for (const k of arr || []) { const q = f(k); q.used = false; c.pins.push(q); set(q.x, q.y, 3); } };
      add(s.L, (j) => ({ x: x - 1, y: y + j, dx: -1, dy: 0, side: 'L' }));
      add(s.R, (j) => ({ x: x + s.w, y: y + j, dx: 1, dy: 0, side: 'R' }));
      add(s.T, (i) => ({ x: x + i, y: y - 1, dx: 0, dy: -1, side: 'T' }));
      add(s.B, (i) => ({ x: x + i, y: y + s.h, dx: 0, dy: 1, side: 'B' }));
      comps.push(c);
      placed++;
    }
  }

  const r2 = kit.rand(p.seed * 13 + 5);
  for (const c of comps) { const vs = VALUES[c.kind]; c.value = vs ? r2.pick(vs) : ''; c.lr = c.w * c.h >= 30 ? 0 : r2(); }
  const segFree = (a, b) => {
    const dx = Math.sign(b[0] - a[0]), dy = Math.sign(b[1] - a[1]);
    let x = a[0], y = a[1];
    for (;;) { if (!free(x, y)) return false; if (x === b[0] && y === b[1]) return true; x += dx; y += dy; }
  };
  const mark = (pts) => {
    for (let k = 0; k < pts.length - 1; k++) {
      const a = pts[k], b = pts[k + 1], dx = Math.sign(b[0] - a[0]), dy = Math.sign(b[1] - a[1]);
      let x = a[0], y = a[1];
      for (;;) { if (at(x, y) === 0) set(x, y, 2); if (x === b[0] && y === b[1]) break; x += dx; y += dy; }
    }
  };
  const chamfer = () => p.style === 'pcb' || (p.style === 'mixed' && r.chance(0.5));
  const route = (pa, pb, bm) => {
    const s = [pa.x + pa.dx, pa.y + pa.dy], e = [pb.x + pb.dx, pb.y + pb.dy];
    if (!free(s[0], s[1]) || !free(e[0], e[1])) return false;
    const cands = [];
    if (bm) {
      if (pa.dx !== 0) cands.push([s, [bm.x, s[1]], [bm.x, e[1]], e], [s, [s[0], bm.y], [e[0], bm.y], e]);
      else cands.push([s, [s[0], bm.y], [e[0], bm.y], e], [s, [bm.x, s[1]], [bm.x, e[1]], e]);
    }
    if (r.chance(0.5)) cands.push([s, [e[0], s[1]], e], [s, [s[0], e[1]], e]); else cands.push([s, [s[0], e[1]], e], [s, [e[0], s[1]], e]);
    for (let k = 0; k < 8; k++) {
      const mx = r.int(Math.min(s[0], e[0]), Math.max(s[0], e[0]));
      const my = r.int(Math.min(s[1], e[1]), Math.max(s[1], e[1]));
      cands.push([s, [mx, s[1]], [mx, e[1]], e], [s, [s[0], my], [e[0], my], e]);
    }
    for (const c of cands) {
      let ok = true;
      for (let k = 0; k < c.length - 1 && ok; k++) ok = segFree(c[k], c[k + 1]);
      if (!ok) continue;
      mark(c);
      traces.push({ pts: simplify([[pa.x, pa.y], ...c, [pb.x, pb.y]]), cham: chamfer() });
      pa.used = pb.used = true;
      if (sch && r.chance(0.3)) dots.push([pa.x, pa.y]);
      return true;
    }
    return false;
  };
  const facing = (A, B) => {
    const dx = B.x + B.w / 2 - (A.x + A.w / 2), dy = B.y + B.h / 2 - (A.y + A.h / 2);
    const h = dx > 0 ? 'R' : 'L', v = dy > 0 ? 'B' : 'T';
    for (const sd of Math.abs(dx) > Math.abs(dy) ? [h, v] : [v, h]) if (A.pins.some((q) => !q.used && q.side === sd)) return sd;
    return null;
  };
  const wired = comps.filter((c) => c.pins.length);
  const nConn = Math.round(wired.length * p.connections);
  for (let t = 0; t < nConn && wired.length > 1; t++) {
    const big = wired.filter((c) => c.pins.length >= 6);
    const A = big.length && r.chance(0.65) ? r.pick(big) : r.pick(wired);
    const near = wired.filter((c) => c !== A).map((c) => [c, Math.abs(c.x + c.w / 2 - A.x - A.w / 2) + Math.abs(c.y + c.h / 2 - A.y - A.h / 2)]).sort((a, b) => a[1] - b[1]);
    const nearBig = near.filter(([c]) => c.pins.length >= 6);
    const pool = nearBig.length && r.chance(0.7) ? nearBig : near;
    const B = pool[r.int(0, Math.min(3, pool.length - 1))][0];
    const sa = facing(A, B), sb = facing(B, A);
    if (!sa || !sb) continue;
    const pa = A.pins.filter((q) => !q.used && q.side === sa), pb = B.pins.filter((q) => !q.used && q.side === sb);
    const k = Math.max(1, Math.min(pa.length, pb.length, Math.round(p.bus * r.range(0.7, 1))));
    const i0 = r.int(0, pa.length - k), j0 = r.int(0, pb.length - k), rev = r.chance(0.5);
    const a0 = pa[i0], b0 = pb[j0];
    const bx = Math.round((a0.x + b0.x) / 2 + r.range(-0.25, 0.25) * Math.abs(a0.x - b0.x));
    const by = Math.round((a0.y + b0.y) / 2 + r.range(-0.25, 0.25) * Math.abs(a0.y - b0.y));
    const sg = rev ? -1 : 1;
    for (let i = 0; i < k; i++) route(pa[i0 + i], pb[rev ? j0 + k - 1 - i : j0 + i], { x: bx + i * sg, y: by + i * sg });
  }
  for (const c of comps) for (const q of c.pins) {
    if (q.used || !r.chance(p.stubs * maskAt(q.x, q.y))) continue;
    let x = q.x, y = q.y, dx = q.dx, dy = q.dy, steps = 0;
    const pts = [[x, y]], long = sch && r.chance(0.12);
    let len = long ? 9999 : r.int(1, 6);
    for (let leg = 0; leg < 2; leg++) {
      let n = 0;
      while (n < len && free(x + dx, y + dy)) { x += dx; y += dy; set(x, y, 2); n++; }
      steps += n;
      if (n) pts.push([x, y]);
      if (leg === 0) {
        if (r.chance(0.5)) break;
        const sg = r.chance(0.5) ? 1 : -1;
        [dx, dy] = [dy * sg, dx * sg];
        len = long ? 9999 : r.int(1, 5);
      }
    }
    if (steps < 1) continue;
    q.used = true;
    traces.push({ pts: simplify(pts), cham: chamfer() });
    ends.push({ x, y, dx, dy, t: r.int(0, 3), pcb: p.style === 'pcb' || (p.style === 'mixed' && r.chance(0.5)) });
  }
  if (p.style !== 'schematic') {
    const nv = Math.round((area / 90) * p.density);
    for (let t = 0; t < nv; t++) {
      const x = r.int(1, cols - 2), y = r.int(1, rows - 2);
      if (free(x, y) && free(x + 1, y) && free(x - 1, y) && free(x, y + 1) && free(x, y - 1) && r() < maskAt(x, y)) { set(x, y, 2); vias.push([x, y]); }
    }
  }
  return { comps, traces, ends, vias, holes, dots };
}

defineTool({
  render(ctx, p) {
    const { g, width: W, height: H, px, state } = ctx;
    const Wd = W / px, Hd = H / px, md = (Math.min(Wd, Hd) * p.margin) / 100;
    const cols = Math.max(12, Math.floor((Wd - 2 * md) / p.cellSize)), rows = Math.max(12, Math.floor((Hd - 2 * md) / p.cellSize));
    const u = p.cellSize * px, ox = (W - cols * u) / 2, oy = (H - rows * u) / 2;
    // Title block, reserved in the grid so nothing is placed under it.
    const tt = p.titleType, lt = p.labelType;
    const title = (p.titleText || '').trim();
    const sub = 'DWG-' + String(p.seed).padStart(4, '0') + '  /  SHEET 1 OF 1';
    let tb = null;
    if (title) {
      const ms = (s, t) => { let m = null; try { m = kit.type.measure(s, t); } catch (e) {} const sz = t.size || 12 * px; return { width: m && m.width > 0 ? m.width : s.length * sz * 0.62, height: m && m.height > 0 ? m.height : sz * 1.2 }; };
      const m1 = ms(title, tt), m2 = ms(sub, lt);
      const pad = u * 1.2;
      const bw = Math.ceil((Math.max(m1.width, m2.width) + pad * 2) / u), bh = Math.ceil((m1.height + m2.height + pad * 2.8) / u);
      const off = p.frame ? 4 : 1;
      if (bw + off + 2 < cols && bh + 2 < rows) tb = { x: cols - bw - off, y: rows - bh - 1, w: bw, h: bh, pad, h1: m1.height };
    }
    const key = [p.style, p.seed, p.density, p.compScale, p.connections, p.bus, p.stubs, p.frame, cols, rows, p.maskType, p.maskScale, p.maskStrength, p.maskInvert, tb ? [tb.x, tb.y, tb.w, tb.h].join(',') : ''].join('|');
    if (state.key !== key) { state.key = key; state.L = build(p, cols, rows, tb); }
    const L = state.L;
    const X = (i) => ox + (i + 0.5) * u, Y = (j) => oy + (j + 0.5) * u;

    g.fillStyle = p.background;
    g.fillRect(0, 0, W, H);
    g.lineCap = 'round';
    g.lineJoin = 'round';

    if (p.grid > 0) {
      g.strokeStyle = p.ink;
      g.lineWidth = 0.5 * px;
      for (const major of [false, true]) {
        g.globalAlpha = Math.min(1, p.grid * (major ? 1.8 : 0.6));
        const step = major ? u * 5 : u;
        g.beginPath();
        for (let x = ox % step; x <= W; x += step) { g.moveTo(x, 0); g.lineTo(x, H); }
        for (let y = oy % step; y <= H; y += step) { g.moveTo(0, y); g.lineTo(W, y); }
        g.stroke();
      }
      g.globalAlpha = 1;
    }

    const lw = p.lineWeight * px;
    const R = (a, b, w, h) => g.rect(a, b, w, h);
    const C = (x, y, rad) => { g.moveTo(x + rad, y); g.arc(x, y, rad, 0, TAU); };
    const Ln = (a, b, c, d) => { g.moveTo(a, b); g.lineTo(c, d); };
    const acc = [], dots = L.dots.map(([i, j]) => [X(i), Y(j)]);

    const drawComp = (c) => {
      const d = u * 0.14;
      const cx0 = ox + c.x * u, cy0 = oy + c.y * u, cx1 = ox + (c.x + c.w) * u, cy1 = oy + (c.y + c.h) * u;
      const x0 = cx0 + d, y0 = cy0 + d, x1 = cx1 - d, y1 = cy1 - d;
      const mx = (x0 + x1) / 2, my = (y0 + y1) / 2, w = x1 - x0, h = y1 - y0, m = Math.min(w, h), hz = w >= h;
      for (const q of c.pins) {
        const qx = X(q.x), qy = Y(q.y);
        Ln(qx, qy, q.dx ? (q.dx < 0 ? x0 : x1) : qx, q.dy ? (q.dy < 0 ? y0 : y1) : qy);
      }
      const A = (t, o) => (hz ? [x0 + w * t, my + o] : [mx + o, y0 + h * t]);
