function makeSvg(W, H) {
  const out = [];
  let d = '';
  const f = (v) => (+v.toFixed(2)).toString();
  const o = {
    fillStyle: '#000', strokeStyle: '#000', lineWidth: 1, lineJoin: 'round', lineCap: 'round', globalAlpha: 1, dash: [],
    setLineDash(a) { o.dash = a; },
    beginPath() { d = ''; },
    moveTo(x, y) { d += 'M' + f(x) + ' ' + f(y); },
    lineTo(x, y) { d += (d ? 'L' : 'M') + f(x) + ' ' + f(y); },
    closePath() { d += 'Z'; },
    rect(x, y, w, h) { d += 'M' + f(x) + ' ' + f(y) + 'H' + f(x + w) + 'V' + f(y + h) + 'H' + f(x) + 'Z'; },
    ellipse(x, y, rx, ry, rot, a0, a1) {
      const n = Math.max(8, Math.ceil((Math.abs(a1 - a0) / (Math.PI * 2)) * 140));
      for (let i = 0; i <= n; i++) {
        const a = a0 + ((a1 - a0) * i) / n;
        o.lineTo(x + rx * Math.cos(a), y + ry * Math.sin(a));
      }
    },
    arc(x, y, r, a0, a1) { o.ellipse(x, y, r, r, 0, a0, a1); },
    fill() { out.push('<path d="' + d + '" fill="' + o.fillStyle + '" stroke="none"' + (o.globalAlpha < 1 ? ' opacity="' + o.globalAlpha + '"' : '') + '/>'); },
    stroke() {
      out.push('<path d="' + d + '" fill="none" stroke="' + o.strokeStyle + '" stroke-width="' + f(o.lineWidth) + '" stroke-linecap="' + o.lineCap + '" stroke-linejoin="' + o.lineJoin + '"' +
        (o.dash.length ? ' stroke-dasharray="' + o.dash.map(f).join(' ') + '"' : '') + (o.globalAlpha < 1 ? ' opacity="' + f(o.globalAlpha) + '"' : '') + '/>');
    },
    fillRect(x, y, w, h) { out.push('<rect x="' + f(x) + '" y="' + f(y) + '" width="' + f(w) + '" height="' + f(h) + '" fill="' + o.fillStyle + '"/>'); },
    toString() { return '<svg xmlns="http://www.w3.org/2000/svg" width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '">' + out.join('') + '</svg>'; },
  };
