}

function drawScene(g, W, H, px, time, p) {
  {
    const S = (Math.min(W, H) / 1000) * 1.15;
    const r = kit.rand(p.seed);
    const t = (p.tilt * Math.PI) / 180, ct = Math.cos(t), st = Math.sin(t);
