defineTool({
  animated: true,
  render(ctx, p) {
    const { g, width: W, height: H, px, state } = ctx;
    const { clamp } = kit.math;
    const c = Math.max(4, p.cellSize * px);
    const cols = Math.ceil(W / c), rows = Math.ceil(H / c);
    const nw = cols + 1, nh = rows + 1;

