    const F = state.F;
    const n = kit.noise(p.seed);
    const t = ctx.time * p.speed * 0.3;
    const sc = p.scale / Math.max(nw, nh) * (nw > nh ? 1 : 1) * 1.0;
    for (let j = 0; j < nh; j++) for (let i = 0; i < nw; i++) {
      const k = j * nw + i;
