    g.fillStyle = p.bg;
    g.fillRect(0, 0, W, H);

    const L = p.levels;
    const th = [];
    for (let k = 0; k < L; k++) th.push((k + 1) / (L + 1) + p.threshold);
    const lvl = (v) => { let s = 0; for (let k = 0; k < L; k++) if (v > th[k]) s++; return s; };

    // Band fill (low-res buffer scaled up, pixel-crisp).
    if (p.fill > 0) {
      const buf = kit.buffer(cols, rows);
