      const d32 = new Uint32Array(img.data.buffer);
      const bgc = kit.color.parse(p.bg);
      const pal = [];
      for (let k = 0; k <= L; k++) {
        const m = kit.color.mix(bgc, p.accent, (k / L) * p.fill);
        pal.push((255 << 24) | (m[2] << 16) | (m[1] << 8) | m[0]);
      }
      for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) d32[j * cols + i] = pal[lvl(F[j * nw + i])];
