      g.fillStyle = p.accent;
      g.lineWidth = Math.max(1, px * 0.9);
      g.beginPath();
      for (let k = 0; k < count; k++) {
        const x = r() * W, y = r() * H;
        const v = F[clamp(Math.round(y / c), 0, rows) * nw + clamp(Math.round(x / c), 0, cols)];
