          g.moveTo(x + p.dotSize * px, y);
          g.arc(x, y, p.dotSize * px, 0, kit.math.TAU);
        }
      }
      g.stroke();
    }
  },
});

defineTool({
  render(ctx, p) {
    const { g, width: W, height: H, px, state } = ctx;
    const { clamp } = kit.math;

    // Working grid: one dither "pixel" = p.pixelSize screen pixels.
    const size = Math.max(1, p.pixelSize * px);
    const w = Math.ceil(W / size), h = Math.ceil(H / size);
    const values = new Float32Array(w * h);

    if (p.source === 'image') {
      if (state.src !== p.image || state.w !== w || state.h !== h) {
        state.src = p.image; state.w = w; state.h = h;
        // Luminance of the image cropped to the grid, computed once per image and size.
        const d = p.image.fit(w, h).pixels();
        state.lum = new Float32Array(w * h);
        for (let i = 0; i < w * h; i++) state.lum[i] = (0.2126 * d[i * 4] + 0.7152 * d[i * 4 + 1] + 0.0722 * d[i * 4 + 2]) / 255;
      }
      values.set(state.lum);
    } else {
      const key = p.seed + ':' + p.noiseScale + ':' + w + 'x' + h;
      if (state.noiseKey !== key) {
        state.noiseKey = key;
        const n = kit.noise(p.seed);
        const sc = p.noiseScale / Math.max(w, h);
        state.noise = new Float32Array(w * h);
        for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) state.noise[y * w + x] = n.fbm2(x * sc, y * sc, 5) * 0.5 + 0.5;
      }
      values.set(state.noise);
    }

    for (let i = 0; i < values.length; i++) values[i] = clamp((values[i] - 0.5) * p.contrast + 0.5 + p.brightness, 0, 1);

    let out;
    if (p.algorithm === 'floyd' || p.algorithm === 'atkinson') {
      out = kit.dither.diffuse(values, w, h, p.algorithm, p.levels);
    } else {
      out = new Float32Array(w * h);
      const q = p.levels - 1;
      for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
        const i = y * w + x;
        out[i] = clamp(Math.floor(values[i] * q + kit.dither.threshold(x, y, p.algorithm)) / q, 0, 1);
      }
    }

    // Precomputed palette: `levels` tones from shadow to highlight.
    const pal = [];
    for (let k = 0; k < p.levels; k++) pal.push(kit.color.mix(p.dark, p.light, k / (p.levels - 1)));

    const buf = kit.buffer(w, h);
    const data = buf.g.createImageData(w, h);
    const px32 = new Uint32Array(data.data.buffer);
    const pal32 = pal.map((c) => (255 << 24) | (c[2] << 16) | (c[1] << 8) | c[0]); // RGBA little-endian
    const q = p.levels - 1;
    for (let i = 0; i < out.length; i++) px32[i] = pal32[Math.round(out[i] * q)];
    buf.g.putImageData(data, 0, 0);
    g.imageSmoothingEnabled = false;
    g.drawImage(buf.canvas, 0, 0, w * size, h * size);
  },
});

function hash(x, y, s) {
  let h = (x * 374761393 + y * 668265263 + s * 2147483647) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

// Returns 0 (ground), 1 (thread) or 2 (accent thread) for a cell at |offset| (ax, ay) from the center.
function cellVal(ax, ay, p, P) {
  const dx = P.cx - ax, dy = P.cy - ay;
  const d = Math.min(dx, dy), far = Math.max(dx, dy);
  const u = dx < dy ? ay : ax;
  const bw = p.bw;
  const acc = p.twoTone ? 2 : 1;
  if (p.corner && dx < P.S && dy < P.S) {
    const S = P.S, lx = dx, ly = dy;
    if (lx === 0 || ly === 0 || lx === S - 1 || ly === S - 1) return 1;
    if (lx === 1 || ly === 1 || lx === S - 2 || ly === S - 2) return 0;
    const cc = (S - 1) / 2, ex = lx - cc, ey = ly - cc;
    if (Math.abs(ex) < 0.6 || Math.abs(ey) < 0.6) return 0;
    return Math.hypot(ex, ey) < S * 0.44 ? acc : 0;
  }
  if (d < bw) {
    if (d === 0 || d === bw - 1) return 1;
    const hw = (bw - 1) / 2, t = d - hw;
    switch (p.border) {
      case 'checker': return (u + d) % 2 === 0 ? 1 : 0;
      case 'dashes': return u % 4 < 2 ? 1 : 0;
      case 'diamonds': {
        const k = Math.abs((u % 8) - 4), q = (4 - k) / 4 + Math.abs(t) / hw;
        return (q <= 1.05 && q >= 0.6) || (k === 4 && Math.abs(t) < 0.5) ? 1 : 0;
      }
      default: {
        const k = ((u % 8) - 3.5) / 3.5, q = k * k + (t / hw) * (t / hw);
        return q <= 1.1 && q >= 0.45 ? 1 : 0;
      }
    }
  }
  const Fd = bw + 8;
  if (d === Fd && p.frame) return 1;
  if (d < Fd) {
    if (!p.band || far < Fd + 2) return 0;
    const zz = d - (bw + 4), k = u % 8, kk = Math.min(k, 8 - k), dist = kk + Math.abs(zz);
    return (dist <= 3 && dist >= 2) || dist === 0 ? 1 : 0;
  }
  const r = Math.hypot(ax, ay), r0 = P.rf * p.rosette;
  if (r < r0 + 1) {
    if (r < 1.3) return acc;
    const th = Math.atan2(ay, ax);
    const rad = r0 * (0.5 + 0.5 * Math.pow(Math.abs(Math.cos(p.petals * th)), 0.7));
    if (r < rad) return !(ax < 0.6 || ay < 0.6) || r < 2.2 ? acc : 0;
    return 0;
  }
  if (p.ring && r < r0 + 4) return Math.abs(r - (r0 + 2.5)) < 0.75 ? 1 : 0;
  if (p.spiral > 0) {
    const Rs = P.rf * p.spiral + 2;
    const cs = [[P.Rx * 0.62 + P.jx, P.Ry * p.scrollPos + P.jy], [P.Rx * 0.3 - P.jx, P.Ry * 0.68 - P.jy]];
    for (let q = 0; q < 2; q++) {
      const ex = ax - cs[q][0], ey = ay - cs[q][1], rr = Math.hypot(ex, ey);
      if (rr < Rs) {
        const sgn = (p.dir === 'ccw' ? 1 : -1) * (q ? -1 : 1);
        const v = rr / p.pitch + sgn * Math.atan2(ey, ex) / (Math.PI * 2);
        return v - Math.floor(v) < 0.45 ? 1 : 0;
      }
      if (rr < Rs + 1.2) return 0;
    }
  }
  if (p.fill > 0 && r > r0 + 3 && d > Fd + 2) {
    const lx = ax % 4, ly = ay % 4;
    const hh = hash(Math.floor(ax / 4), Math.floor(ay / 4), p.seed);
    if (hh < p.fill * 1.4) return (lx === 1 && ly <= 2) || (ly === 1 && lx <= 2) ? 1 : 0;
    if (hh < p.fill * 1.4 + 0.3) return lx === 1 && ly === 1 ? 1 : 0;
  }
  return 0;
}

defineTool({
  render(ctx, p) {
    const { g, width: W, height: H, px } = ctx;
    const st = ctx.state;
    const cols = Math.round(p.cells) | 1;
    const cw0 = W / cols;
    let rows = Math.round(H / cw0) | 1;
    if (rows < 21) rows = 21;
    const key = [cols, rows, p.seed, p.border, p.bw, p.corner, p.band, p.frame, p.petals, p.rosette, p.ring, p.spiral, p.pitch, p.scrollPos, p.dir, p.fill, p.twoTone].join('|');
    if (st.key !== key) {
      st.key = key;
      const r = kit.rand(p.seed);
      const cx = (cols - 1) / 2, cy = (rows - 1) / 2, Fd = p.bw + 8;
      const Rx = Math.max(4, cx - Fd), Ry = Math.max(4, cy - Fd);
      const P = {
        cx, cy, Rx, Ry, rf: Math.min(Rx, Ry),
        S: p.bw + Math.round(Math.min(cx, cy) * 0.2),
        jx: (r() - 0.5) * Rx * 0.12, jy: (r() - 0.5) * Ry * 0.12,
      };
      const grid = new Uint8Array(cols * rows);
      for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) {
        grid[j * cols + i] = cellVal(Math.abs(i - cx), Math.abs(j - cy), p, P);
      }
      st.grid = grid;
    }
    const cw = W / cols, ch = H / rows;
    g.fillStyle = p.ground;
    g.fillRect(0, 0, W, H);
    if (p.gridlines) {
      g.strokeStyle = kit.color.css(kit.color.mix(p.ground, '#000000', 0.3));
      g.lineWidth = Math.max(1, px * 0.6);
      g.beginPath();
      for (let i = 0; i <= cols; i++) { const x = Math.round(i * cw); g.moveTo(x, 0); g.lineTo(x, H); }
      for (let j = 0; j <= rows; j++) { const y = Math.round(j * ch); g.moveTo(0, y); g.lineTo(W, y); }
      g.stroke();
    }
    const gx = cw * p.gap, gy = ch * p.gap;
    for (let pass = 1; pass <= 2; pass++) {
      const col = pass === 1 ? p.ink : p.accent;
      g.fillStyle = col;
      g.strokeStyle = col;
      g.lineWidth = Math.max(1, Math.min(cw, ch) * 0.22);
      g.lineCap = 'round';
      g.beginPath();
      for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) {
        if (st.grid[j * cols + i] !== pass) continue;
        const x0 = i * cw + gx, y0 = j * ch + gy, w = cw - gx * 2 + (p.gap < 0.01 ? 0.5 : 0), h = ch - gy * 2 + (p.gap < 0.01 ? 0.5 : 0);
