          g.moveTo(x0 + w, y0 + h / 2);
          g.ellipse(x0 + w / 2, y0 + h / 2, w / 2, h / 2, 0, 0, Math.PI * 2);
        } else if (p.shape === 'cross') {
          const m = 0.15;
          g.moveTo(x0 + w * m, y0 + h * m); g.lineTo(x0 + w * (1 - m), y0 + h * (1 - m));
